{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipe = pd.read_csv('pipeline_output.csv')

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for it in items:
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            vals.append(int(v))

    # self harm flag based on q9
    q9 = row['phq9_9']
    if pd.isna(q9) or q9 == -9 or q9 < 0 or q9 > 3:
        sh_flag = np.nan
    else:
        sh_flag = True if int(q9) >= 1 else False

    n_answered = sum(not np.isnan(v) for v in vals)
    if n_answered < 8:
        return np.nan, np.nan, np.nan, sh_flag
    elif n_answered == 8:
        s = sum(v for v in vals if not np.isnan(v))
        # scale up: sum * 9 / 8, half rounds up (4.5 -> 5)
        # Python round(4.5) is 4 (round to even). We need half rounding up!
        raw_scaled = s * 9 / 8.0
        # half rounding up: floor(x + 0.5)
        total = int(np.floor(raw_scaled + 0.5))
        prorated = True
    else:
        total = int(sum(vals))
        prorated = False

    # band
    if total <= 4:
        band = 'none-minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    elif total <= 19:
        band = 'moderately severe'
    else:
        band = 'severe'

    return total, band, prorated, sh_flag

def score_gad7(row):
    items = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    for it in items:
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            vals.append(int(v))

    n_answered = sum(not np.isnan(v) for v in vals)
    if n_answered < 6:
        return np.nan, np.nan, np.nan
    elif n_answered == 6:
        s = sum(v for v in vals if not np.isnan(v))
        raw_scaled = s * 7 / 6.0
        total = int(np.floor(raw_scaled + 0.5))
        prorated = True
    else:
        total = int(sum(vals))
        prorated = False

    if total <= 4:
        band = 'minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    else:
        band = 'severe'

    return total, band, prorated

def score_rses(row):
    items = [f'rses_{i}' for i in range(1, 11)]
    rev_items = {3, 5, 8, 9, 10}
    vals = []
    for i, it in enumerate(items, 1):
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            iv = int(v)
            if i in rev_items:
                vals.append(3 - iv)
            else:
                vals.append(iv)

    n_answered = sum(not np.isnan(v) for v in vals)
    if n_answered < 9:
        return np.nan, np.nan
    elif n_answered == 9:
        s = sum(v for v in vals if not np.isnan(v))
        raw_scaled = s * 10 / 9.0
        total = int(np.floor(raw_scaled + 0.5))
        prorated = True
    else:
        total = int(sum(vals))
        prorated = False

    return total, prorated

my_results = []
for idx, row in raw.iterrows():
    p_tot, p_band, p_pro, p_sh = score_phq9(row)
    g_tot, g_band, g_pro = score_gad7(row)
    r_tot, r_pro = score_rses(row)
    my_results.append({
        'respondent_id': row['respondent_id'],
        'phq9_total': p_tot,
        'phq9_band': p_band,
        'phq9_prorated': p_pro,
        'phq9_self_harm_flag': p_sh,
        'gad7_total': g_tot,
        'gad7_band': g_band,
        'gad7_prorated': g_pro,
        'rses_total': r_tot,
        'rses_prorated': r_pro
    })

my_df = pd.DataFrame(my_results)

# Compare with pipe
for col in pipe.columns:
    if col == 'respondent_id':
        continue
    # compare series
    s1 = my_df[col]
    s2 = pipe[col]

    # Handle booleans and NaNs and floats/ints/strings properly for comparison
    # In pipe, totals might be float because of NaN.
    if s1.dtype in [float, int] and s2.dtype in [float, int]:
        mismatch = ~np.isclose(s1.fillna(-999), s2.fillna(-999), equal_nan=True)
    else:
        # object/bool/string
        mismatch = s1.fillna('NA').astype(str) != s2.fillna('NA').astype(str)

    n_mismatch = mismatch.sum()
    print(f"Column {col}: {n_mismatch} mismatches")
    if n_mismatch > 0:
        diffs = pd.DataFrame({'id': raw['respondent_id'], 'mine': s1, 'pipe': s2, 'mismatch': mismatch})
        print(diffs[diffs['mismatch']].head(10))
