{"code":"# Let's double check PHQ-9 and GAD-7 across all 505 rows with our correct scorers (and even check if there are any other columns/edges).
import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipe = pd.read_csv('pipeline_output.csv')

# Verify every single column of pipe against our scorers (with RSES using 4 - v)
def run_full_qa():
    errors = 0
    for idx, row in raw.iterrows():
        # PHQ9
        p_items = [row[f'phq9_{i}'] for i in range(1, 10)]
        p_vals = [int(v) for v in p_items if not pd.isna(v) and v != -9 and 0 <= v <= 3]
        p_ans = len(p_vals)
        if p_ans < 8:
            p_tot = np.nan
            p_band = np.nan
            p_pro = np.nan
        elif p_ans == 8:
            p_tot = int(np.floor(sum(p_vals) * 9 / 8.0 + 0.5))
            p_pro = True
        else:
            p_tot = sum(p_vals)
            p_pro = False

        if pd.isna(p_tot):
            p_band = np.nan
        elif p_tot <= 4:
            p_band = 'none-minimal'
        elif p_tot <= 9:
            p_band = 'mild'
        elif p_tot <= 14:
            p_band = 'moderate'
        elif p_tot <= 19:
            p_band = 'moderately severe'
        else:
            p_band = 'severe'

        q9 = row['phq9_9']
        if pd.isna(q9) or q9 == -9 or not (0 <= q9 <= 3):
            p_sh = np.nan
        else:
            p_sh = True if int(q9) >= 1 else False

        # GAD7
        g_items = [row[f'gad7_{i}'] for i in range(1, 8)]
        g_vals = [int(v) for v in g_items if not pd.isna(v) and v != -9 and 0 <= v <= 3]
        g_ans = len(g_vals)
        if g_ans < 6:
            g_tot = np.nan
            g_band = np.nan
            g_pro = np.nan
        elif g_ans == 6:
            g_tot = int(np.floor(sum(g_vals) * 7 / 6.0 + 0.5))
            g_pro = True
        else:
            g_tot = sum(g_vals)
            g_pro = False

        if pd.isna(g_tot):
            g_band = np.nan
        elif g_tot <= 4:
            g_band = 'minimal'
        elif g_tot <= 9:
            g_band = 'mild'
        elif g_tot <= 14:
            g_band = 'moderate'
        else:
            g_band = 'severe'

        # RSES (pipeline version with 4 - v for items 3, 5, 8, 9, 10)
        r_items = []
        for i in range(1, 11):
            v = row[f'rses_{i}']
            if pd.isna(v) or v == -9 or not (0 <= v <= 3):
                r_items.append(np.nan)
            else:
                iv = int(v)
                if i in {3, 5, 8, 9, 10}:
                    r_items.append(4 - iv)
                else:
                    r_items.append(iv)
        r_vals = [v for v in r_items if not np.isnan(v)]
        r_ans = len(r_vals)
        if r_ans < 9:
            r_tot = np.nan
            r_pro = np.nan
        elif r_ans == 9:
            r_tot = int(np.floor(sum(r_vals) * 10 / 9.0 + 0.5))
            r_pro = True
        else:
            r_tot = sum(r_vals)
            r_pro = False

        # Compare with pipe row
        p_row = pipe.loc[idx]

        checks = [
            ('phq9_total', p_tot, p_row['phq9_total']),
            ('phq9_band', p_band, p_row['phq9_band']),
            ('phq9_prorated', p_pro, p_row['phq9_prorated']),
            ('phq9_self_harm_flag', p_sh, p_row['phq9_self_harm_flag']),
            ('gad7_total', g_tot, p_row['gad7_total']),
            ('gad7_band', g_band, p_row['gad7_band']),
            ('gad7_prorated', g_pro, p_row['gad7_prorated']),
            ('rses_total', r_tot, p_row['rses_total']),
            ('rses_prorated', r_pro, p_row['rses_prorated'])
        ]

        for col, mine, theirs in checks:
            if pd.isna(mine) and pd.isna(theirs):
                continue
            if isinstance(mine, bool) or isinstance(theirs, bool):
                if mine != theirs:
                    print(f"Mismatch at row {idx} {col}: mine={mine}, pipe={theirs}")
                    errors += 1
            elif isinstance(mine, str) or isinstance(theirs, str):
                if str(mine) != str(theirs):
                    print(f"Mismatch at row {idx} {col}: mine={mine}, pipe={theirs}")
                    errors += 1
            else:
                if not np.isclose(float(mine), float(theirs), equal_nan=True):
                    print(f"Mismatch at row {idx} {col}: mine={mine}, pipe={theirs}")
                    errors += 1
    print("Total verified mismatches with pipeline using 4-v formula:", errors)

run_full_qa()
